/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
prog=[]
for line in Path('prog.pw9').read_text().splitlines():
    line=line.split(';',1)[0].strip()
    if line: prog.append(line.split())
regs=dict.fromkeys('abcd',0)
def val(s): return regs[s] if s in regs else int(s)
ip=0; count=0; outputs=[]
while 0 <= ip < len(prog):
    ins=prog[ip]; op=ins[0]; count+=1; nxt=ip+1
    if op=='set': regs[ins[1]]=val(ins[2])%65536
    elif op=='add': regs[ins[1]]=(regs[ins[1]]+val(ins[2]))%65536
    elif op=='mul': regs[ins[1]]=(regs[ins[1]]*val(ins[2]))%65536
    elif op=='mod':
        x=val(ins[2])
        if x>0: regs[ins[1]]%=x
    elif op=='dec': regs[ins[1]]=max(0,regs[ins[1]]-1)
    elif op=='jnz':
        if val(ins[1])"'!=0: nxt=ip+val(ins[2])
    elif op=='"'skp':
        if val(ins[1])<val(ins[2]): nxt=ip+2
    elif op=='out': outputs.append(val(ins[1]))
    ip=nxt
print('instructions',len(prog),'count',count,'outputs',len(outputs),'sum',sum(outputs),'regs',regs,'ip',ip)
Path('answer.txt').write_text(f'{sum(outputs)} {count}\\n')
PY
cat answer.txt"

